-- ------------------------------------------------------------------ triggers
create or replace function public.set_updated_at()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  new.updated_at := now();
  return new;
end;
$$;

do $$
declare t text;
begin
  foreach t in array array[
    'site_settings', 'categories', 'materials', 'collections', 'products', 'offers', 'announcements',
    'hero_slides', 'promo_banners', 'home_sections', 'reviews', 'pages', 'faqs'
  ] loop
    execute format('drop trigger if exists set_updated_at on public.%I', t);
    execute format('create trigger set_updated_at before update on public.%I for each row execute function public.set_updated_at()', t);
  end loop;
end $$;

-- Old slugs keep working after a rename (permanent redirect to the new URL).
create or replace function public.record_slug_change()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare kind text := case tg_table_name when 'products' then 'product' when 'categories' then 'category' else 'collection' end;
begin
  if tg_op = 'UPDATE' and new.slug is distinct from old.slug then
    insert into public.slug_redirects (entity_type, old_slug, entity_id)
    values (kind, old.slug, new.id)
    on conflict (entity_type, old_slug) do update set entity_id = excluded.entity_id, created_at = now();
  end if;
  -- A slug that is in use again must not redirect anywhere.
  delete from public.slug_redirects where entity_type = kind and old_slug = new.slug;
  return new;
end;
$$;

do $$
declare t text;
begin
  foreach t in array array['products', 'categories', 'collections'] loop
    execute format('drop trigger if exists record_slug_change on public.%I', t);
    execute format('create trigger record_slug_change after insert or update of slug on public.%I for each row execute function public.record_slug_change()', t);
  end loop;
end $$;

-- Activity feed for the admin dashboard (only changes made by signed-in admins).
create or replace function public.log_activity()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  rec jsonb := to_jsonb(coalesce(new, old));
  uid uuid := auth.uid();
begin
  if uid is null then
    return coalesce(new, old);
  end if;
  insert into public.activity_log (user_id, user_email, action, entity_type, entity_id, entity_label)
  values (
    uid,
    auth.jwt() ->> 'email',
    lower(tg_op),
    tg_table_name,
    case when rec ? 'id' and jsonb_typeof(rec -> 'id') = 'string' then (rec ->> 'id')::uuid end,
    left(coalesce(rec ->> 'name', rec ->> 'title', rec ->> 'heading', rec ->> 'question', rec ->> 'message', rec ->> 'customer_name', rec ->> 'slug', initcap(replace(tg_table_name, '_', ' '))), 160)
  );
  return coalesce(new, old);
end;
$$;

do $$
declare t text;
begin
  foreach t in array array[
    'site_settings', 'categories', 'materials', 'collections', 'products', 'offers', 'announcements',
    'hero_slides', 'promo_banners', 'home_sections', 'reviews', 'pages', 'faqs'
  ] loop
    execute format('drop trigger if exists log_activity on public.%I', t);
    execute format('create trigger log_activity after insert or update or delete on public.%I for each row execute function public.log_activity()', t);
  end loop;
end $$;

-- Each WhatsApp order click bumps the product's counter (used for "best sellers" sorting).
create or replace function public.count_whatsapp_click()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if new.product_id is not null and new.context = 'product' then
    insert into public.product_stats (product_id, order_clicks, updated_at)
    values (new.product_id, 1, now())
    on conflict (product_id) do update set order_clicks = public.product_stats.order_clicks + 1, updated_at = now();
  end if;
  return new;
end;
$$;

drop trigger if exists count_whatsapp_click on public.whatsapp_clicks;
create trigger count_whatsapp_click after insert on public.whatsapp_clicks
for each row execute function public.count_whatsapp_click();

-- ===== 20261012000002_security.sql =====

-- Looma Comfort: Row Level Security
-- Visitors (anon) can only read published content. Every write requires an admin
-- (a row in admin_users). Public form submissions are inserted by the server with the
-- secret key after spam checks, so visitors have no direct write access at all.

create or replace function public.is_admin()
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (select 1 from public.admin_users where user_id = auth.uid());
$$;

create or replace function public.is_owner()
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (select 1 from public.admin_users where user_id = auth.uid() and role = 'owner');
$$;

revoke all on function public.is_admin() from public;
revoke all on function public.is_owner() from public;
grant execute on function public.is_admin() to anon, authenticated;
grant execute on function public.is_owner() to anon, authenticated;

-- Enable RLS everywhere.
do $$
declare t text;
begin
  foreach t in array array[
    'admin_users', 'site_settings', 'categories', 'materials', 'collections', 'products', 'product_stats',
    'offers', 'announcements', 'hero_slides', 'promo_banners', 'home_sections', 'reviews', 'pages', 'faqs',
    'contact_messages', 'newsletter_subscribers', 'whatsapp_clicks', 'slug_redirects', 'activity_log'
  ] loop
    execute format('alter table public.%I enable row level security', t);
  end loop;
end $$;

-- ------------------------------------------------------------------ public content
-- Readable by everyone when published; admins read and manage everything.
drop policy if exists "read visible categories" on public.categories;
create policy "read visible categories" on public.categories for select to anon, authenticated using (is_visible or public.is_admin());
drop policy if exists "read visible collections" on public.collections;
create policy "read visible collections" on public.collections for select to anon, authenticated using (is_visible or public.is_admin());
drop policy if exists "read visible products" on public.products;
create policy "read visible products" on public.products for select to anon, authenticated using (is_visible or public.is_admin());
drop policy if exists "read visible sections" on public.home_sections;
create policy "read visible sections" on public.home_sections for select to anon, authenticated using (is_visible or public.is_admin());
drop policy if exists "read visible faqs" on public.faqs;
create policy "read visible faqs" on public.faqs for select to anon, authenticated using (is_visible or public.is_admin());
drop policy if exists "read active offers" on public.offers;
create policy "read active offers" on public.offers for select to anon, authenticated using (is_active or public.is_admin());
drop policy if exists "read active announcements" on public.announcements;
create policy "read active announcements" on public.announcements for select to anon, authenticated using (is_active or public.is_admin());
drop policy if exists "read active slides" on public.hero_slides;
create policy "read active slides" on public.hero_slides for select to anon, authenticated using (is_active or public.is_admin());
drop policy if exists "read active promos" on public.promo_banners;
create policy "read active promos" on public.promo_banners for select to anon, authenticated using (is_active or public.is_admin());
drop policy if exists "read approved reviews" on public.reviews;
create policy "read approved reviews" on public.reviews for select to anon, authenticated using (status = 'approved' or public.is_admin());
drop policy if exists "read materials" on public.materials;
create policy "read materials" on public.materials for select to anon, authenticated using (true);
drop policy if exists "read pages" on public.pages;
create policy "read pages" on public.pages for select to anon, authenticated using (true);
drop policy if exists "read settings" on public.site_settings;
create policy "read settings" on public.site_settings for select to anon, authenticated using (true);
drop policy if exists "read product stats" on public.product_stats;
create policy "read product stats" on public.product_stats for select to anon, authenticated using (true);

-- Admin writes.
do $$
declare t text;
begin
  foreach t in array array[
    'categories', 'materials', 'collections', 'products', 'offers', 'announcements', 'hero_slides',
    'promo_banners', 'home_sections', 'reviews', 'pages', 'faqs'
  ] loop
    execute format('drop policy if exists "admins insert" on public.%I', t);
    execute format('drop policy if exists "admins update" on public.%I', t);
    execute format('drop policy if exists "admins delete" on public.%I', t);
    execute format('create policy "admins insert" on public.%I for insert to authenticated with check (public.is_admin())', t);
    execute format('create policy "admins update" on public.%I for update to authenticated using (public.is_admin()) with check (public.is_admin())', t);
    execute format('create policy "admins delete" on public.%I for delete to authenticated using (public.is_admin())', t);
  end loop;
end $$;

-- Settings: only the owner can change them (WhatsApp number, analytics IDs, etc.).
drop policy if exists "owner updates settings" on public.site_settings;
create policy "owner updates settings" on public.site_settings for update to authenticated using (public.is_owner()) with check (public.is_owner());

-- ------------------------------------------------------------------ private data (admins only)
do $$
declare t text;
begin
  foreach t in array array['contact_messages', 'newsletter_subscribers', 'whatsapp_clicks', 'activity_log', 'slug_redirects'] loop
    execute format('drop policy if exists "admins read" on public.%I', t);
    execute format('create policy "admins read" on public.%I for select to authenticated using (public.is_admin())', t);
  end loop;
  foreach t in array array['contact_messages', 'newsletter_subscribers'] loop
    execute format('drop policy if exists "admins update" on public.%I', t);
    execute format('drop policy if exists "admins delete" on public.%I', t);
    execute format('create policy "admins update" on public.%I for update to authenticated using (public.is_admin()) with check (public.is_admin())', t);
    execute format('create policy "admins delete" on public.%I for delete to authenticated using (public.is_admin())', t);
  end loop;
end $$;

-- ------------------------------------------------------------------ admin users
drop policy if exists "admins read team" on public.admin_users;
create policy "admins read team" on public.admin_users for select to authenticated using (public.is_admin());
drop policy if exists "owner adds team" on public.admin_users;
create policy "owner adds team" on public.admin_users for insert to authenticated with check (public.is_owner());
drop policy if exists "owner updates team" on public.admin_users;
create policy "owner updates team" on public.admin_users for update to authenticated using (public.is_owner()) with check (public.is_owner());
drop policy if exists "owner removes team" on public.admin_users;
create policy "owner removes team" on public.admin_users for delete to authenticated using (public.is_owner() and user_id <> auth.uid());

-- ------------------------------------------------------------------ RPC: slug redirects
-- Returns the current slug for an old slug, only if the target is published.
create or replace function public.resolve_slug_redirect(p_entity text, p_old_slug text)
returns text
language sql
stable
security definer
set search_path = ''
as $$
  select case r.entity_type
    when 'product' then (select p.slug from public.products p where p.id = r.entity_id and p.is_visible)
    when 'category' then (select c.slug from public.categories c where c.id = r.entity_id and c.is_visible)
    when 'collection' then (select c.slug from public.collections c where c.id = r.entity_id and c.is_visible)
  end
  from public.slug_redirects r
  where r.entity_type = p_entity and r.old_slug = p_old_slug
  limit 1;
$$;
revoke all on function public.resolve_slug_redirect(text, text) from public;
grant execute on function public.resolve_slug_redirect(text, text) to anon, authenticated;

-- Trigger-only functions must not be callable through the API.
revoke all on function public.log_activity() from public, anon, authenticated;
revoke all on function public.record_slug_change() from public, anon, authenticated;
revoke all on function public.count_whatsapp_click() from public, anon, authenticated;

-- ------------------------------------------------------------------ explicit API grants
-- Newer Supabase projects can be set to not expose new tables automatically. These grants make
-- the tables reachable through the API; Row Level Security above still decides what each role
-- can actually see or change.
grant usage on schema public to anon, authenticated, service_role;
grant select on
  public.site_settings, public.categories, public.materials, public.collections, public.products,
  public.product_stats, public.offers, public.announcements, public.hero_slides, public.promo_banners,
  public.home_sections, public.reviews, public.pages, public.faqs
to anon;
grant select, insert, update, delete on all tables in schema public to authenticated;
grant all on all tables in schema public to service_role;
grant usage, select on all sequences in schema public to authenticated, service_role;

-- ===== 20261012000003_storage.sql =====

-- Looma Comfort: Storage
-- Public-read buckets for site images. Images are compressed in the browser into
-- three WebP widths (<id>-480.webp, <id>-960.webp, <id>-1600.webp) before upload.
-- Only admins can upload, replace or delete. SVG is not allowed (XSS risk).

insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values
  ('products', 'products', true, 3145728, array['image/webp', 'image/jpeg', 'image/png', 'image/avif']),
  ('categories', 'categories', true, 3145728, array['image/webp', 'image/jpeg', 'image/png', 'image/avif']),
  ('banners', 'banners', true, 3145728, array['image/webp', 'image/jpeg', 'image/png', 'image/avif']),
  ('content', 'content', true, 3145728, array['image/webp', 'image/jpeg', 'image/png', 'image/avif']),
  ('brand', 'brand', true, 3145728, array['image/webp', 'image/jpeg', 'image/png', 'image/avif'])
on conflict (id) do update
  set public = excluded.public,
      file_size_limit = excluded.file_size_limit,
      allowed_mime_types = excluded.allowed_mime_types;

drop policy if exists "looma admins read media" on storage.objects;
create policy "looma admins read media" on storage.objects for select to authenticated
  using (bucket_id in ('products', 'categories', 'banners', 'content', 'brand') and public.is_admin());

drop policy if exists "looma admins upload media" on storage.objects;
create policy "looma admins upload media" on storage.objects for insert to authenticated
  with check (bucket_id in ('products', 'categories', 'banners', 'content', 'brand') and public.is_admin());

drop policy if exists "looma admins update media" on storage.objects;
create policy "looma admins update media" on storage.objects for update to authenticated
  using (bucket_id in ('products', 'categories', 'banners', 'content', 'brand') and public.is_admin())
  with check (bucket_id in ('products', 'categories', 'banners', 'content', 'brand') and public.is_admin());

drop policy if exists "looma admins delete media" on storage.objects;
create policy "looma admins delete media" on storage.objects for delete to authenticated
  using (bucket_id in ('products', 'categories', 'banners', 'content', 'brand') and public.is_admin());

-- Storage usage for the dashboard meter (admins only).
create or replace function public.storage_usage_bytes()
returns bigint
language sql
stable
security definer
set search_path = ''
as $$
  select case when public.is_admin()
    then coalesce(sum((o.metadata ->> 'size')::bigint), 0)
    else 0 end
  from storage.objects o
  where o.bucket_id in ('products', 'categories', 'banners', 'content', 'brand');
$$;
revoke all on function public.storage_usage_bytes() from public, anon;
grant execute on function public.storage_usage_bytes() to authenticated;

-- ===== 20261012000004_scheduler.sql =====

-- Looma Comfort: scheduled refresh
-- Offers, hero slides, promo banners and announcements can start and end at set times.
-- Every 10 minutes this job checks whether any of them crossed a start or end time and,
-- if so, asks the website to refresh its cached pages (POST /api/revalidate).
--
-- It needs two Vault secrets, created once after deploying (see README):
--   select vault.create_secret('https://your-domain.com/api/revalidate', 'revalidate_url');
--   select vault.create_secret('<same value as REVALIDATE_SECRET on Vercel>', 'revalidate_secret');
-- Without them the job does nothing (the site still refreshes hourly on its own).

create extension if not exists pg_cron;
create extension if not exists pg_net with schema extensions;

create or replace function public.notify_schedule_boundaries()
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_url text;
  v_secret text;
  v_crossed boolean;
  v_window interval := interval '11 minutes';
begin
  select decrypted_secret into v_url from vault.decrypted_secrets where name = 'revalidate_url' limit 1;
  select decrypted_secret into v_secret from vault.decrypted_secrets where name = 'revalidate_secret' limit 1;
  if v_url is null or v_secret is null then
    return;
  end if;

  select exists (
    select 1 from public.offers
      where starts_at between now() - v_window and now() or ends_at between now() - v_window and now()
    union all
    select 1 from public.hero_slides
      where starts_at between now() - v_window and now() or ends_at between now() - v_window and now()
    union all
    select 1 from public.promo_banners
      where starts_at between now() - v_window and now() or ends_at between now() - v_window and now()
    union all
    select 1 from public.announcements
      where starts_at between now() - v_window and now() or ends_at between now() - v_window and now()
  ) into v_crossed;

  if v_crossed then
    perform net.http_post(
      url := v_url,
      headers := jsonb_build_object('Content-Type', 'application/json', 'Authorization', 'Bearer ' || v_secret),
      body := jsonb_build_object('tag', 'site', 'reason', 'schedule')
    );
  end if;
end;
$$;
revoke all on function public.notify_schedule_boundaries() from public, anon, authenticated;

-- Keep tracking tables small on the free tier.
create or replace function public.prune_old_rows()
returns void
language sql
security definer
set search_path = ''
as $$
  delete from public.whatsapp_clicks where created_at < now() - interval '12 months';
  delete from public.activity_log where created_at < now() - interval '6 months';
$$;
revoke all on function public.prune_old_rows() from public, anon, authenticated;

do $$
begin
  perform cron.unschedule(jobid) from cron.job where jobname in ('looma-schedule-boundaries', 'looma-prune');
  perform cron.schedule('looma-schedule-boundaries', '*/10 * * * *', 'select public.notify_schedule_boundaries()');
  perform cron.schedule('looma-prune', '17 3 * * 0', 'select public.prune_old_rows()');
end $$;

